/**
 * Each time offered arrives a little after the one ranked above it. The wait is on the fade only:
 * the tint that answers the pointer never waits.
 */
const ARRIVAL_DELAY = ['delay-0', 'delay-[0ms,75ms]', 'delay-[0ms,150ms]'];

const ROW =
  'flex items-center gap-2.5 rounded-lg p-2 transition-[background-color,opacity] duration-[150ms,300ms] starting:opacity-0';

const EXAMPLE =
  'focus-visible:ring-ring/25 hover:bg-foreground/[0.05] w-full cursor-pointer rounded-lg px-2.5 py-2 text-start text-[13px] leading-5 text-pretty transition-colors duration-150 outline-none focus-visible:ring-[3px]';

function rowToneOf(isHot: boolean) {
  if (isHot) {
    return 'bg-foreground/[0.05]';
  }
  return undefined;
}

/** The best time carries the one primary action of the block. */
function bookVariantOf(rank: number) {
  if (rank === 1) {
    return 'default';
  }
  return 'outline';
}

function calendarsWordOf(count: number) {
  if (count === 1) {
    return '1 calendar';
  }
  return `${count} calendars`;
}

/** Thu 19, 11:00 to 11:45. */
function slotLabelOf(slot: Slot) {
  const day = dayOf(slot.day);
  return `${day.label} ${day.date}, ${timeRangeOf(slot.start, slot.end)}`;
}

type ExamplesProps = {
  onExample: (text: string) => void;
};

function Examples({ onExample }: ExamplesProps) {
  return (
    <div className='flex flex-col gap-1.5'>
      <p className='text-muted-foreground px-2.5 text-xs'>
        Ask in your own words, or start from one of these
      </p>
      <ul className='flex flex-col'>
        {EXAMPLES.map((example) => (
          <li key={example}>
            <button
              type='button'
              onClick={() => onExample(example)}
              className={EXAMPLE}
            >
              {example}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

type SuggestionRowProps = {
  suggestion: Suggestion;
  isHot: boolean;
  isPressed: boolean;
  onHover: (rank: number | null) => void;
  onBook: (rank: number) => void;
};

function SuggestionRow({
  suggestion,
  isHot,
  isPressed,
  onHover,
  onBook,
}: SuggestionRowProps) {
  const { rank } = suggestion;

  return (
    <li
      onPointerEnter={() => onHover(rank)}
      onPointerLeave={() => onHover(null)}
      className={cn(ROW, ARRIVAL_DELAY[rank - 1], rowToneOf(isHot))}
    >
      <LetterTile initial={String(rank)} />
      <div className='flex min-w-0 flex-1 flex-col'>
        <p className='truncate text-[13px] leading-5 font-medium tabular-nums'>
          {slotLabelOf(suggestion)}
        </p>
        <p className='text-muted-foreground text-xs text-pretty'>
          {suggestion.reason}
        </p>
      </div>
      <Button
        type='button'
        size='sm'
        variant={bookVariantOf(rank)}
        data-book={rank}
        aria-label={`Book ${slotLineOf(suggestion)}`}
        onClick={() => onBook(rank)}
        onFocus={() => onHover(rank)}
        onBlur={() => onHover(null)}
        className={pressedSolidOf(isPressed)}
      >
        Book
      </Button>
    </li>
  );
}

type BookedProps = {
  booking: Booking;
  onUndo: () => void;
};

/** The bar under the card empties over the five seconds the undo stays. */
function Booked({ booking, onUndo }: BookedProps) {
  const guests = guestNamesOf(booking.attendees);

  return (
    <div className='bg-success/10 relative flex flex-col gap-2.5 overflow-hidden rounded-lg p-3 transition-opacity duration-200 starting:opacity-0'>
      <div className='flex items-start gap-2'>
        <CircleCheckIcon className='text-success-foreground mt-0.5 size-4 shrink-0' />
        <div className='flex min-w-0 flex-col'>
          <p className='text-[13px] leading-5 font-medium tabular-nums'>
            Booked {slotLabelOf(booking)}
          </p>
          <p className='text-xs'>With {guests}, on every calendar</p>
        </div>
      </div>
      <div className='flex items-center gap-2 ps-6'>
        <Button
          type='button'
          variant='outline'
          size='sm'
          data-undo={booking.id}
          onClick={onUndo}
        >
          <UndoIcon />
          Undo
        </Button>
        <span className='text-xs'>for 5 seconds</span>
      </div>
      <span
        aria-hidden='true'
        className='bg-success/60 absolute inset-x-0 bottom-0 h-0.5 origin-left scale-x-0 transition-transform duration-[5000ms] ease-linear motion-reduce:hidden starting:scale-x-100'
      />
    </div>
  );
}

export type SuggestionPanelProps = {
  search: Search | null;
  hot: number | null;
  /** The meeting that can still be undone. */
  booking: Booking | null;
  pressed: string | null;
  onExample: (text: string) => void;
  onHover: (rank: number | null) => void;
  onBook: (rank: number) => void;
  onUndo: () => void;
  onClear: () => void;
};

/** What the assistant says back: what it is checking, the times it found, then the one that was booked. */
export function SuggestionPanel({
  search,
  hot,
  booking,
  pressed,
  onExample,
  onHover,
  onBook,
  onUndo,
  onClear,
}: SuggestionPanelProps) {
  if (!search) {
    return <Examples onExample={onExample} />;
  }
  const requestLine = requestLineOf(search.request);

  if (search.status === 'shading') {
    const calendars = calendarsWordOf(search.request.attendees.length);
    return (
      <div className='flex flex-col gap-1 px-2.5 py-2'>
        <p className='flex items-center gap-2 text-[13px] leading-5 font-medium'>
          <LoaderIcon
            aria-hidden='true'
            className='text-muted-foreground size-4 animate-spin'
          />
          Checking {calendars}
        </p>
        <p className='text-muted-foreground ps-6 text-xs'>{requestLine}</p>
      </div>
    );
  }

  if (search.status === 'booked') {
    if (!booking) {
      return null;
    }
    return <Booked key={booking.id} booking={booking} onUndo={onUndo} />;
  }

  return (
    <div className='flex flex-col gap-1.5'>
      <div className='flex items-center gap-2 ps-2.5'>
        <p className='text-muted-foreground min-w-0 flex-1 truncate text-xs'>
          {requestLine}
        </p>
        <Button
          type='button'
          variant='ghost'
          size='sm'
          data-search-clear
          onClick={onClear}
          className='text-muted-foreground'
        >
          Clear
        </Button>
      </div>
      <ol aria-label='Times found' className='flex flex-col gap-0.5'>
        {search.suggestions.map((suggestion) => (
          <SuggestionRow
            key={suggestion.rank}
            suggestion={suggestion}
            isHot={hot === suggestion.rank}
            isPressed={pressed === `book-${suggestion.rank}`}
            onHover={onHover}
            onBook={onBook}
          />
        ))}
      </ol>
    </div>
  );
}

import {
  DAY_END,
  DAY_START,
  dayIndexOf,
  dayOf,
  DAYS,
  PEOPLE,
  personOf,
  type DayId,
  type PersonId,
} from './data';

export type MeetingRequest = {
  minutes: number;
  /** You are always part of it. */
  attendees: PersonId[];
  days: DayId[];
  /** The part of the day the meeting has to sit in, in minutes since midnight. */
  from: number;
  until: number;
};

export const NO_ATTENDEE_LINE = 'Say who should join: Maya, Jonas or everyone.';

const DEFAULT_MINUTES = 30;

const SHORTEST_MINUTES = 15;

const LONGEST_MINUTES = 240;

const NOON = 12 * 60;

const AFTER_LUNCH = 13 * 60;

const MINUTES = /\b(\d+) ?(?:minutes|minute|mins|min|m)\b/;

const HOURS = /\b(\d+) ?(?:hours|hour|hrs|hr|h)\b/;

const EVERYONE_PHRASES = ['everyone', 'everybody', 'all three', 'the team'];

const PERSON_PHRASES: Record<PersonId, string[]> = {
  you: [],
  maya: ['maya'],
  jonas: ['jonas'],
};

const DAY_PHRASES: Record<DayId, string[]> = {
  mon: ['monday', 'mon', 'today'],
  tue: ['tuesday', 'tue', 'tomorrow'],
  wed: ['wednesday', 'wed'],
  thu: ['thursday', 'thu'],
  fri: ['friday', 'fri'],
};

const LATE_WEEK_PHRASES = [
  'before the weekend',
  'end of the week',
  'late this week',
];

const EARLY_WEEK_PHRASES = ['early this week', 'start of the week'];

const MORNING_PHRASES = ['morning', 'before lunch', 'before noon'];

const AFTERNOON_PHRASES = ['afternoon', 'after lunch'];

const LATE_WEEK: DayId[] = ['thu', 'fri'];

const EARLY_WEEK: DayId[] = ['mon', 'tue'];

const ALL_DAYS = DAYS.map((day) => day.id);

/** Lower case words between single spaces, with a space at both ends so a phrase is matched whole. */
function sentenceOf(text: string) {
  const lowered = text.toLowerCase();
  const spaced = lowered.replace(/[^a-z0-9]+/g, ' ');
  const trimmed = spaced.trim();
  return ` ${trimmed} `;
}

function names(sentence: string, phrases: string[]) {
  return phrases.some((phrase) => sentence.includes(` ${phrase} `));
}

function countIn(sentence: string, unit: RegExp) {
  const match = unit.exec(sentence);
  if (!match) {
    return null;
  }
  return Number(match[1]);
}

function boundedMinutes(minutes: number) {
  const atLeastShortest = Math.max(SHORTEST_MINUTES, minutes);
  return Math.min(LONGEST_MINUTES, atLeastShortest);
}

/** The lengths said in words. A longer phrase is read before the shorter one it contains. */
function spelledMinutesOf(sentence: string) {
  if (names(sentence, ['an hour and a half'])) {
    return 90;
  }
  if (names(sentence, ['half an hour'])) {
    return 30;
  }
  if (names(sentence, ['an hour', 'one hour'])) {
    return 60;
  }
  return DEFAULT_MINUTES;
}

/** 45 minutes, 2 hours, 1 hour 30 minutes, or a length said in words. */
function minutesOf(sentence: string) {
  const minutes = countIn(sentence, MINUTES);
  const hours = countIn(sentence, HOURS);
  const hasFigure = minutes !== null || hours !== null;
  if (!hasFigure) {
    return spelledMinutesOf(sentence);
  }
  const fromHours = (hours ?? 0) * 60;
  const fromMinutes = minutes ?? 0;
  return boundedMinutes(fromHours + fromMinutes);
}

function guestsOf(sentence: string) {
  if (names(sentence, EVERYONE_PHRASES)) {
    return PEOPLE.filter((person) => person.id !== 'you');
  }
  return PEOPLE.filter((person) => names(sentence, PERSON_PHRASES[person.id]));
}

function daysOf(sentence: string) {
  if (names(sentence, LATE_WEEK_PHRASES)) {
    return LATE_WEEK;
  }
  if (names(sentence, EARLY_WEEK_PHRASES)) {
    return EARLY_WEEK;
  }
  const named = ALL_DAYS.filter((day) => names(sentence, DAY_PHRASES[day]));
  if (named.length > 0) {
    return named;
  }
  return ALL_DAYS;
}

type DayPart = Pick<MeetingRequest, 'from' | 'until'>;

function dayPartOf(sentence: string): DayPart {
  if (names(sentence, MORNING_PHRASES)) {
    return { from: DAY_START, until: NOON };
  }
  if (names(sentence, AFTERNOON_PHRASES)) {
    return { from: AFTER_LUNCH, until: DAY_END };
  }
  return { from: DAY_START, until: DAY_END };
}

/**
 * Reads a plain request into a meeting to place: how long, with whom, on which days and in which
 * part of the day. A handful of word lists, no model. It returns nothing when nobody is named.
 */
export function requestOfQuestion(text: string): MeetingRequest | null {
  const sentence = sentenceOf(text);
  const guests = guestsOf(sentence);
  if (guests.length === 0) {
    return null;
  }
  const guestIds = guests.map((person) => person.id);
  const dayPart = dayPartOf(sentence);
  return {
    minutes: minutesOf(sentence),
    attendees: ['you', ...guestIds],
    days: daysOf(sentence),
    ...dayPart,
  };
}

/** Maya and Jonas. */
export function guestNamesOf(attendees: PersonId[]) {
  const guests = attendees.filter((id) => id !== 'you');
  const shortNames = guests.map((id) => personOf(id).shortName);
  return shortNames.join(' and ');
}

function areNeighbours(days: DayId[]) {
  const first = dayIndexOf(days[0]);
  return days.every((day, index) => dayIndexOf(day) === first + index);
}

/** Thu, Thu to Fri, Tue and Thu. */
export function daysLabelOf(days: DayId[]) {
  const labels = days.map((day) => dayOf(day).label);
  const isRange = days.length > 1 && areNeighbours(days);
  if (isRange) {
    const last = labels[labels.length - 1];
    return `${labels[0]} to ${last}`;
  }
  return labels.join(' and ');
}

/** 45 min with Maya and Jonas, Thu to Fri. */
export function requestLineOf(request: MeetingRequest) {
  const guests = guestNamesOf(request.attendees);
  const days = daysLabelOf(request.days);
  return `${request.minutes} min with ${guests}, ${days}`;
}

import type { MeetingRequest } from './ask';
import {
  DAY_END,
  DAY_START,
  dayIndexOf,
  personOf,
  type DayId,
  type PersonId,
} from './data';

export type Slot = {
  day: DayId;
  start: number;
  end: number;
};

/** Time one person is taken: a meeting of theirs, or one booked here that they attend. */
export type Busy = Slot & {
  person: PersonId;
  title: string;
};

export type Suggestion = Slot & {
  /** 1 is the best time found. */
  rank: number;
  reason: string;
};

type Candidate = Slot & {
  score: number;
  reason: string;
};

/** Candidate times start on the hour and on the half hour. */
const STEP_MINUTES = 30;

/** Less room than this between two meetings reads as back to back. */
const BREATHING_MINUTES = 15;

const LUNCH_START = 12 * 60;

const LUNCH_END = 13 * 60;

const LATE_AFTER = 17 * 60;

/** Two times offered on one day sit at least this far apart, so the three are real choices. */
const SPREAD_MINUTES = 60;

const SUGGESTION_COUNT = 3;

const BACK_TO_BACK_COST = 40;

const LATE_COST = 30;

const LUNCH_COST = 25;

const BEST_SCORE = 100;

function overlaps(first: Slot, second: Slot) {
  const isSameDay = first.day === second.day;
  const startsBeforeEnd = first.start < second.end;
  const endsAfterStart = first.end > second.start;
  return isSameDay && startsBeforeEnd && endsAfterStart;
}

function isFree(taken: Busy[], slot: Slot) {
  return !taken.some((busy) => overlaps(busy, slot));
}

/** The meeting one of them leaves right before the slot, if any. */
function meetingJustBefore(taken: Busy[], slot: Slot) {
  return taken.find((busy) => {
    const isSameDay = busy.day === slot.day;
    const gap = slot.start - busy.end;
    const endsBefore = gap >= 0;
    const isTooShort = gap < BREATHING_MINUTES;
    return isSameDay && endsBefore && isTooShort;
  });
}

/** The meeting one of them has to reach right after the slot, if any. */
function meetingJustAfter(taken: Busy[], slot: Slot) {
  return taken.find((busy) => {
    const isSameDay = busy.day === slot.day;
    const gap = busy.start - slot.end;
    const startsAfter = gap >= 0;
    const isTooShort = gap < BREATHING_MINUTES;
    return isSameDay && startsAfter && isTooShort;
  });
}

function whoOf(attendees: PersonId[]) {
  if (attendees.length > 2) {
    return 'Everyone';
  }
  return 'Both';
}

function ownedTitleOf(busy: Busy) {
  const owner = personOf(busy.person);
  return `${owner.possessive} ${busy.title}`;
}

/**
 * A slot starts from the best score and pays for what makes it worse. Its reason names the first
 * thing a person would mind, or says there is none.
 */
function candidateOf(taken: Busy[], slot: Slot, who: string): Candidate {
  const before = meetingJustBefore(taken, slot);
  const after = meetingJustAfter(taken, slot);
  const startsBeforeLunchEnds = slot.start < LUNCH_END;
  const endsAfterLunchStarts = slot.end > LUNCH_START;
  const runsIntoLunch = startsBeforeLunchEnds && endsAfterLunchStarts;
  const isLate = slot.end > LATE_AFTER;
  let score = BEST_SCORE;
  let reason = `${who} free, no back-to-back`;
  if (isLate) {
    score -= LATE_COST;
    reason = `${who} free, last thing in the day`;
  }
  if (runsIntoLunch) {
    score -= LUNCH_COST;
    reason = `${who} free, runs into lunch`;
  }
  if (after) {
    score -= BACK_TO_BACK_COST;
    reason = `${who} free, ends as ${ownedTitleOf(after)} starts`;
  }
  if (before) {
    score -= BACK_TO_BACK_COST;
    reason = `${who} free, straight after ${ownedTitleOf(before)}`;
  }
  return { ...slot, score, reason };
}

function candidatesOn(
  day: DayId,
  request: MeetingRequest,
  taken: Busy[],
  who: string
) {
  const candidates: Candidate[] = [];
  const first = Math.max(DAY_START, request.from);
  const dayEnd = Math.min(DAY_END, request.until);
  const lastStart = dayEnd - request.minutes;
  for (let start = first; start <= lastStart; start += STEP_MINUTES) {
    const slot = { day, start, end: start + request.minutes };
    if (isFree(taken, slot)) {
      candidates.push(candidateOf(taken, slot, who));
    }
  }
  return candidates;
}

/** The best score first; between equals the earlier day, then the earlier hour. */
function byPreference(first: Candidate, second: Candidate) {
  if (first.score !== second.score) {
    return second.score - first.score;
  }
  const dayOrder = dayIndexOf(first.day) - dayIndexOf(second.day);
  if (dayOrder !== 0) {
    return dayOrder;
  }
  return first.start - second.start;
}

function isTooClose(candidate: Candidate, chosen: Candidate) {
  const isSameDay = candidate.day === chosen.day;
  const startsBeforeReach = candidate.start < chosen.end + SPREAD_MINUTES;
  const endsAfterReach = candidate.end > chosen.start - SPREAD_MINUTES;
  return isSameDay && startsBeforeReach && endsAfterReach;
}

/**
 * Works out when everyone asked is free for the length asked, and keeps the best three: no model
 * is called. `taken` holds the busy time of every person; only the attendees are looked at.
 */
export function suggestionsOf(
  request: MeetingRequest,
  taken: Busy[]
): Suggestion[] {
  const theirs = taken.filter((busy) =>
    request.attendees.includes(busy.person)
  );
  const who = whoOf(request.attendees);
  const candidates = request.days.flatMap((day) =>
    candidatesOn(day, request, theirs, who)
  );
  candidates.sort(byPreference);
  const chosen: Candidate[] = [];
  for (const candidate of candidates) {
    const isCrowded = chosen.some((kept) => isTooClose(candidate, kept));
    if (isCrowded) {
      continue;
    }
    chosen.push(candidate);
    if (chosen.length === SUGGESTION_COUNT) {
      break;
    }
  }
  return chosen.map((candidate, index) => ({
    day: candidate.day,
    start: candidate.start,
    end: candidate.end,
    rank: index + 1,
    reason: candidate.reason,
  }));
}

/** The busy time of the attendees on one day, as bands that do not overlap: what the calendar shades. */
export function busyBandsOf(
  taken: Busy[],
  attendees: PersonId[],
  day: DayId
): Slot[] {
  const theirs = taken.filter((busy) => {
    const isAttendee = attendees.includes(busy.person);
    return isAttendee && busy.day === day;
  });
  const ordered = [...theirs];
  ordered.sort((first, second) => first.start - second.start);
  const bands: Slot[] = [];
  for (const busy of ordered) {
    const last = bands[bands.length - 1];
    const joinsLast = last !== undefined && busy.start <= last.end;
    if (joinsLast) {
      last.end = Math.max(last.end, busy.end);
      continue;
    }
    bands.push({ day, start: busy.start, end: busy.end });
  }
  return bands;
}

import { DAY_END, DAY_START } from './data';

export type Timed = {
  id: string;
  start: number;
  end: number;
};

/** Where a block sits in its day: which column of how many, among the blocks it overlaps. */
export type Place = {
  column: number;
  columns: number;
};

/** The box of a block inside its day, as shares of the width and of the height of the day. */
export type Box = {
  top: string;
  height: string;
  left: string;
  width: string;
};

const DAY_SPAN = DAY_END - DAY_START;

function byStart(first: Timed, second: Timed) {
  if (first.start !== second.start) {
    return first.start - second.start;
  }
  return second.end - first.end;
}

/** The first column whose last block has ended, or a new one. */
function freeColumnOf(columnEnds: number[], start: number) {
  const free = columnEnds.findIndex((end) => end <= start);
  if (free === -1) {
    return columnEnds.length;
  }
  return free;
}

/**
 * Blocks that overlap in time share the width of the day, side by side. Blocks are read in order of
 * start; a run of blocks that touch one another is a cluster, and every block of a cluster takes
 * one column of as many as the cluster needed.
 */
export function placesOf(items: Timed[]) {
  const ordered = [...items];
  ordered.sort(byStart);
  const places = new Map<string, Place>();
  let cluster: Timed[] = [];
  let columnEnds: number[] = [];
  let clusterEnd = 0;

  function closeCluster() {
    for (const item of cluster) {
      const place = places.get(item.id);
      if (place) {
        place.columns = columnEnds.length;
      }
    }
    cluster = [];
    columnEnds = [];
  }

  for (const item of ordered) {
    const startsAfterCluster = item.start >= clusterEnd;
    if (startsAfterCluster) {
      closeCluster();
    }
    const column = freeColumnOf(columnEnds, item.start);
    columnEnds[column] = item.end;
    places.set(item.id, { column, columns: 1 });
    cluster.push(item);
    clusterEnd = Math.max(clusterEnd, item.end);
  }
  closeCluster();
  return places;
}

function shareOf(part: number, whole: number) {
  const share = (part / whole) * 100;
  return `${share}%`;
}

export function boxOf(item: Timed, place: Place | undefined): Box {
  const column = place?.column ?? 0;
  const columns = place?.columns ?? 1;
  return {
    top: shareOf(item.start - DAY_START, DAY_SPAN),
    height: shareOf(item.end - item.start, DAY_SPAN),
    left: shareOf(column, columns),
    width: shareOf(1, columns),
  };
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';

import {
  guestNamesOf,
  NO_ATTENDEE_LINE,
  requestOfQuestion,
  type MeetingRequest,
} from './ask';
import {
  dayOf,
  EVENTS,
  EXAMPLES,
  PEOPLE,
  timeRangeOf,
  type DayId,
  type PersonId,
} from './data';
import { suggestionsOf, type Busy, type Slot, type Suggestion } from './find';

export type SearchStatus = 'shading' | 'offering' | 'booked';

/** One question and what came of it: first the busy time is shaded, then the times are offered, then one is booked. */
export type Search = {
  request: MeetingRequest;
  suggestions: Suggestion[];
  status: SearchStatus;
};

export type Booking = Slot & {
  /** The demonstration and a person name their bookings apart, so an undo that runs out only ever ends its own. */
  id: string;
  attendees: PersonId[];
  title: string;
};

export type CalendarState = {
  question: string;
  /** Why the last question could not be answered. */
  askHint: string | null;
  /** Whose calendars show. */
  shown: PersonId[];
  /** The day a narrow page shows. */
  day: DayId;
  search: Search | null;
  /** The suggestion under the pointer or the focus. */
  hot: number | null;
  bookings: Booking[];
  /** The booking that can still be undone. */
  undoId: string | null;
  spoken: string;
};

export type CalendarAction =
  | { type: 'questionTyped'; text: string }
  | { type: 'asked' }
  | { type: 'offered' }
  | { type: 'hovered'; rank: number | null }
  | { type: 'booked'; rank: number; id: string }
  | { type: 'undone' }
  | { type: 'undoExpired'; id: string }
  | { type: 'searchCleared' }
  | { type: 'calendarsShown'; shown: PersonId[] }
  | { type: 'dayPicked'; day: DayId };

type Step = SessionStep<CalendarState, CalendarAction>;

export const NO_TIME_LINE =
  'No time fits everyone in that window. Try a shorter meeting or more days.';

const ALL_PEOPLE = PEOPLE.map((person) => person.id);

export const INITIAL: CalendarState = {
  question: '',
  askHint: null,
  shown: ALL_PEOPLE,
  day: 'mon',
  search: null,
  hot: null,
  bookings: [],
  undoId: null,
  spoken: '',
};

function busyOfBooking(booking: Booking): Busy[] {
  return booking.attendees.map((person) => ({
    person,
    day: booking.day,
    start: booking.start,
    end: booking.end,
    title: booking.title,
  }));
}

/** The time every person is taken: their own meetings, and the ones booked here that they attend. */
export function takenOf(bookings: Booking[]): Busy[] {
  const booked = bookings.flatMap(busyOfBooking);
  return [...EVENTS, ...booked];
}

function calendarsWordOf(count: number) {
  if (count === 1) {
    return '1 calendar';
  }
  return `${count} calendars`;
}

function timesWordOf(count: number) {
  if (count === 1) {
    return '1 time found';
  }
  return `${count} times found`;
}

export function slotLineOf(slot: Slot) {
  const day = dayOf(slot.day);
  return `${day.name} ${timeRangeOf(slot.start, slot.end)}`;
}

function unanswered(state: CalendarState, hint: string): CalendarState {
  return { ...state, askHint: hint, spoken: hint };
}

/** A new question settles the last booking: its undo goes, the meeting stays. */
function asked(state: CalendarState): CalendarState {
  const request = requestOfQuestion(state.question);
  if (!request) {
    return unanswered(state, NO_ATTENDEE_LINE);
  }
  const suggestions = suggestionsOf(request, takenOf(state.bookings));
  if (suggestions.length === 0) {
    return unanswered(state, NO_TIME_LINE);
  }
  const shown = ALL_PEOPLE.filter((person) => {
    const isShown = state.shown.includes(person);
    return isShown || request.attendees.includes(person);
  });
  const calendars = calendarsWordOf(request.attendees.length);
  return {
    ...state,
    askHint: null,
    shown,
    day: request.days[0],
    search: { request, suggestions, status: 'shading' },
    hot: null,
    undoId: null,
    spoken: `Checking ${calendars}`,
  };
}

function offered(state: CalendarState): CalendarState {
  const search = state.search;
  if (search?.status !== 'shading') {
    return state;
  }
  const [best] = search.suggestions;
  const times = timesWordOf(search.suggestions.length);
  const spoken = `${times}. Best: ${slotLineOf(best)}. ${best.reason}`;
  return {
    ...state,
    search: { ...search, status: 'offering' },
    day: best.day,
    spoken,
  };
}

function suggestionOf(search: Search, rank: number) {
  return search.suggestions.find((candidate) => candidate.rank === rank);
}

/** A narrow page shows one day: it follows the suggestion a person points at. */
function hovered(state: CalendarState, rank: number | null): CalendarState {
  const search = state.search;
  if (search?.status !== 'offering') {
    return { ...state, hot: null };
  }
  if (rank === null) {
    return { ...state, hot: null };
  }
  const suggestion = suggestionOf(search, rank);
  if (!suggestion) {
    return { ...state, hot: null };
  }
  return { ...state, hot: rank, day: suggestion.day };
}

function booked(state: CalendarState, rank: number, id: string): CalendarState {
  const search = state.search;
  if (search?.status !== 'offering') {
    return state;
  }
  const suggestion = suggestionOf(search, rank);
  if (!suggestion) {
    return state;
  }
  const guests = guestNamesOf(search.request.attendees);
  const booking: Booking = {
    id,
    day: suggestion.day,
    start: suggestion.start,
    end: suggestion.end,
    attendees: search.request.attendees,
    title: `Sync with ${guests}`,
  };
  const spoken = `Booked ${slotLineOf(booking)} with ${guests}. Undo stays for 5 seconds`;
  return {
    ...state,
    question: '',
    askHint: null,
    day: booking.day,
    search: { ...search, status: 'booked' },
    hot: null,
    bookings: [...state.bookings, booking],
    undoId: id,
    spoken,
  };
}

/** The meeting leaves and the times it was picked from are offered again. */
function undone(state: CalendarState): CalendarState {
  const undoId = state.undoId;
  if (undoId === null) {
    return state;
  }
  const bookings = state.bookings.filter((booking) => booking.id !== undoId);
  const next = { ...state, bookings, undoId: null, spoken: 'Booking undone' };
  const search = state.search;
  if (search?.status !== 'booked') {
    return next;
  }
  return { ...next, search: { ...search, status: 'offering' } };
}

function undoExpired(state: CalendarState, id: string): CalendarState {
  if (state.undoId !== id) {
    return state;
  }
  const next = { ...state, undoId: null, spoken: '' };
  if (state.search?.status !== 'booked') {
    return next;
  }
  return { ...next, search: null };
}

function searchCleared(state: CalendarState): CalendarState {
  if (state.search?.status === 'booked') {
    return state;
  }
  return { ...state, search: null, hot: null, spoken: '' };
}

export function reducer(
  state: CalendarState,
  action: CalendarAction
): CalendarState {
  switch (action.type) {
    case 'questionTyped':
      return { ...state, question: action.text, askHint: null };
    case 'asked':
      return asked(state);
    case 'offered':
      return offered(state);
    case 'hovered':
      return hovered(state, action.rank);
    case 'booked':
      return booked(state, action.rank, action.id);
    case 'undone':
      return undone(state);
    case 'undoExpired':
      return undoExpired(state, action.id);
    case 'searchCleared':
      return searchCleared(state);
    case 'calendarsShown':
      return { ...state, shown: action.shown };
    case 'dayPicked':
      return { ...state, day: action.day };
  }
}

/** How long the busy time stays shaded before the times are offered. */
export const THINK_MS = 1200;

export const UNDO_MS = 5000;

const KEY_MS = 40;

const DEMO_BOOKING = 'demo';

const [QUESTION] = EXAMPLES;

function typingSteps(text: string, startAfter: number): Step[] {
  const prefixes = prefixesOf(text);
  return prefixes.map((typed, index) => ({
    after: keyDelayOf(index, startAfter, KEY_MS),
    by: 'demo',
    action: { type: 'questionTyped', text: typed },
  }));
}

/** The question is typed and sent, the assistant shades the busy time and offers three times. */
const ASKING: Step[] = [
  ...typingSteps(QUESTION, 1200),
  { after: 500, by: 'demo', press: 'ask', action: { type: 'asked' } },
  { after: THINK_MS, action: { type: 'offered' } },
];

/** The demonstration looks at each time, books the best one and lets the undo run out. */
const BOOKING: Step[] = [
  { after: 1700, by: 'demo', action: { type: 'hovered', rank: 2 } },
  { after: 1000, by: 'demo', action: { type: 'hovered', rank: 3 } },
  { after: 1000, by: 'demo', action: { type: 'hovered', rank: 1 } },
  {
    after: 1300,
    by: 'demo',
    press: 'book-1',
    action: { type: 'booked', rank: 1, id: DEMO_BOOKING },
  },
  { after: UNDO_MS, action: { type: 'undoExpired', id: DEMO_BOOKING } },
];

export const SCRIPT: Step[] = [...ASKING, ...BOOKING];

function endOf(script: Step[]) {
  let state = INITIAL;
  for (const step of script) {
    state = reducer(state, step.action);
  }
  return state;
}

/** Under reduced motion the three times are on the calendar, waiting for a choice. */
export const RESTING: CalendarState = { ...endOf(ASKING), spoken: '' };

export const LOOP_AFTER_MS = 2800;

